window.__votdWeek && window.__votdWeek({"week":"2028-05-22","reading":"Mosiah 25–28","days":[{"d":"2028-05-22","ref":"Mosiah 25:2","b":"Mosiah","c":25,"v":2,"he":"וַיְהִי מִסְפַּר בְּנֵי נֶפִי וְצֶאֱצָאֵי נֶפִי מְעַט מִמִּסְפַּר עַם זָרַהֶמְלָה אֲשֶׁר הָיָה מִצֶּאֱצָאֵי מוּלֶק וְהַבָּאִים אִתּוֹ הַמִּדְבָּרָה׃","en":"Now there were not so many of the children of Nephi, or so many of those who were descendants of Nephi, as there were of the people of Zarahemla, who was a descendant of Mulek, and those who came with him into the wilderness."},{"d":"2028-05-23","ref":"Mosiah 25:11","b":"Mosiah","c":25,"v":11,"he":"וְעוֹד בַּחֲשָׁבָם עַל־הַלָּמָנִים אֲחֵיהֶם עַל־חַטֹּאתָם וְטֻמְאָתָם וַיִּמָּלְאוּ מַכְאוֹב וְצַעַר לְטוֹבַת נַפְשֹׁתָם׃","en":"And again, when they thought upon the Lamanites, who were their brethren, of their sinful and polluted state, they were filled with pain and anguish for the welfare of their souls."},{"d":"2028-05-24","ref":"Mosiah 26:28","b":"Mosiah","c":26,"v":28,"he":"לָכֵן אֹמֵר אֲנִי לָכֶם כִּי הַמְמָאֵן לִשְׁמֹעַ בְּקוֹלִי אוֹתוֹ לֹא תְקַבְּלוּ בַּעֲדָתִי כִּי־לֹא אֲקַבְּלֶנּוּ בַּיּוֹם הָאַחֲרוֹן׃","en":"Therefore I say unto you, that he that will not hear my voice, the same shall ye not receive into my church, for him I will not receive at the last day."},{"d":"2028-05-25","ref":"Mosiah 26:30","b":"Mosiah","c":26,"v":30,"he":"וְכׇל־אֲשֶׁר יָשׁוּבוּ עַמִּי אֶסְלַח לָהֶם עַל־פִּשְׁעֵיהֶם בִּי׃","en":"Yea, and as often as my people repent will I forgive them their trespasses against me."},{"d":"2028-05-26","ref":"Mosiah 27:9","b":"Mosiah","c":27,"v":9,"he":"וַיְהִי לְמִכְשׁוֹל גָּדוֹל לַעֲדַת הָאֱלֹהִים וַיִּגְנֹב אֶת־לֵב הָעָם וַיָּבֵא מְרִיבוֹת רַבּוֹת בֵּין הָעָם וַיִּתֵּן מָקוֹם לְאוֹיֵב הָאֱלֹהִים לְהַרְאוֹת כֹּחוֹ עֲלֵיהֶם׃","en":"And he became a great hinderment to the prosperity of the church of God; stealing away the hearts of the people; causing much dissension among the people; giving a chance for the enemy of God to exercise his power over them."},{"d":"2028-05-27","ref":"Mosiah 27:24","b":"Mosiah","c":27,"v":24,"he":"כִּי אָמַר שַׁבְתִּי מֵחַטֹּאתַי וּגְאָלַנִי יְהוָה הִנֵּה נוֹלַדְתִּי מֵהָרוּחַ׃","en":"For, said he, I have repented of my sins, and have been redeemed of the Lord; behold I am born of the Spirit."},{"d":"2028-05-28","ref":"Mosiah 28:13","b":"Mosiah","c":28,"v":13,"he":"וַיְתַרְגֵּם אוֹתָם בִּשְׁתֵּי הָאֲבָנִים הַקְּבוּעוֹת בְּתוֹךְ שְׁתֵּי מִסְגְּרוֹת הַקֶּשֶׁת׃","en":"And now he translated them by the means of those two stones which were fastened into the two rims of a bow."}]});
